sys_script.script:
(function executeRule(current, previous /*null when async*/) {
	// Create a gliderecord for the custom table
	var tempGr = new GlideRecord('x_1425578_itsm_u_0_incident_temp');
	tempGr.initialize();

	// Map fields from the current table
	tempGr.incident_number = current.number;
	tempGr.short_description = current.short_description;

	// Insert the new record into the incident_temp
	tempGr.insert();

})(current, previous);
